beforeExample:
class Example {
    boolean isUnderVirtual() { return false; }
    void foo(Example dest) {
        if (dest.isUnderVirtual() == false) {
            System.out.println("Not virtual");
        }
        boolean myFlag = true;
        if (myFlag == false) {
            System.out.println("Flag is false");
        }
    }
}

afterExample:
class Example {
    boolean isUnderVirtual() { return false; }
    void foo(Example dest) {
        if (!dest.isUnderVirtual()) {
            System.out.println("Not virtual");
        }
        boolean myFlag = true;
        if (!myFlag) {
            System.out.println("Flag is false");
        }
    }
}

