class NegativeExample {
    boolean isEnabled() { return true; }
    void bar(NegativeExample obj) {
        if (obj.isEnabled() == true) { // Should not match: '== true' is a different idiom
            System.out.println("Enabled");
        }
        if (obj == null) { // Should not match: Not a boolean comparison to 'false'
            System.out.println("Object is null");
        }
    }
}
